"""Public index of blog series."""
from django.urls import reverse
from django.views.generic import ListView, RedirectView

from zinnia.models import BlogSeries


class SeriesList(ListView):
    template_name = 'zinnia/series_list.html'
    context_object_name = 'all_series'

    def get_queryset(self):
        return BlogSeries.objects.filter(visible=True).order_by('-pk')


class LegacySeriesRedirect(RedirectView):
    """Keep links generated by the old encoded-fragment URL working."""
    permanent = True

    def get_redirect_url(self, pk):
        return '%s#series-%s' % (reverse('zinnia:series_list'), pk)
